5	namespace Kanban.Tests.Unit.Domain;
6	
7	public class UserTests
8	{
9	    private static User ValidUser() =>
10	        new(Guid.NewGuid(), "admin@example.com", "Admin User", SystemRole.Admin,
11	            null, DateTimeOffset.UtcNow, null);
12	
13	    [Fact]
14	    public void Constructor_WhenIdIsEmpty_ThrowsArgumentException()
15	    {
16	        Guid id = Guid.Empty;
17	        var act = () => new User(id, "a@b.com", "Name", SystemRole.Standard,
18	            null, DateTimeOffset.UtcNow, null);
19	        act.Should().Throw<ArgumentException>();
20	    }
21	
22	    [Fact]
23	    public void Constructor_WhenEmailIsEmpty_ThrowsArgumentException()
24	    {
25	        string email = string.Empty;
26	        var act = () => new User(Guid.NewGuid(), email, "Name", SystemRole.Standard,
27	            null, DateTimeOffset.UtcNow, null);
28	        act.Should().Throw<ArgumentException>();
29	    }
30	
31	    [Fact]
32	    public void Constructor_WhenDisplayNameIsEmpty_ThrowsArgumentException()
33	    {
34	        string displayName = string.Empty;
35	        var act = () => new User(Guid.NewGuid(), "a@b.com", displayName, SystemRole.Standard,
36	            null, DateTimeOffset.UtcNow, null);
37	        act.Should().Throw<ArgumentException>();
38	    }
