41	    public void LinkGoogleIdentity_SetsGoogleSub()
42	    {
43	        var user = ValidUser();
44	        string googleSub = "google-sub-123";
45	        user.LinkGoogleIdentity(googleSub);
46	        user.GoogleSub.Should().Be("google-sub-123");
