37	                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
38	                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
39	            })
40	            .Build();
41	
42	    public InvitationService(
43	        IUserRepository userRepository,
44	        IInvitationRepository invitationRepository,
45	        IAuthEventRepository authEventRepository,
46	        IBoardMemberRepository boardMemberRepository,
47	        IDbConnection dbConnection,
48	        IDbConnectionFactory transactionFactory,
