50	    {
51	        Verify.That(userRepository).IsNotNull();
52	        Verify.That(invitationRepository).IsNotNull();
53	        Verify.That(authEventRepository).IsNotNull();
54	        Verify.That(boardMemberRepository).IsNotNull();
55	        Verify.That(dbConnection).IsNotNull();
56	        Verify.That(transactionFactory).IsNotNull();
