58	        _userRepository = userRepository;
59	        _invitationRepository = invitationRepository;
60	        _authEventRepository = authEventRepository;
61	        _boardMemberRepository = boardMemberRepository;
62	        _dbConnection = dbConnection;
63	        _transactionFactory = transactionFactory;
64	        _logger = logger;
65	    }
66	
67	    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
68	        string email,
69	        Guid issuedByUserId,
70	        SystemRole callerRole,
71	        string frontendBaseUrl,
72	        Guid? boardId = null,
73	        BoardRole? boardRole = null,
74	        CancellationToken cancellationToken = default)
75	    {
76	        Verify.That(email).IsNotNull().IsNotEmpty();
77	        Verify.That(issuedByUserId).IsNotDefault();
78	        Verify.That(frontendBaseUrl).IsNotNull().IsNotEmpty();
79	
80	        // System invitations require admin. Board invitations are pre-authorised by the caller
81	        // (BoardMembershipService checks board role before calling here).
82	        if (boardId is null && callerRole != SystemRole.Admin)
83	            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");
84	
85	        return await RetryPolicy.ExecuteAsync(async ct =>
86	        {
87	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
88	            try
89	            {
90	                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
91	                if (existing is not null)
92	                {
93	                    var refreshToken = InvitationToken.Generate();
94	                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
95	                    await _invitationRepository.RefreshTokenAsync(
96	                        existing.Id, refreshToken.Hash, newExpiry, tx);
97	                    tx.Commit();
98	                    _logger.LogInformation(
99	                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
100	                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
101	                }
102	
103	                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
104	                if (registeredUser is not null)
105	                    throw new ConflictException(
106	                        "invite.already_registered", "This email address is already registered.");
107	
108	                var token = InvitationToken.Generate();
109	                var issuedAt = DateTimeOffset.UtcNow;
110	                var invitation = new Invitation(
111	                    id: Guid.NewGuid(),
112	                    email: email,
113	                    issuedByUserId: issuedByUserId,
114	                    tokenHash: token.Hash,
115	                    issuedAt: issuedAt,
116	                    expiresAt: issuedAt.AddDays(7),
117	                    consumedAt: null,
118	                    consumedByUserId: null,
119	                    boardId: boardId,
120	                    boardRole: boardRole);
121	
122	                await _invitationRepository.InsertAsync(invitation, tx);
123	
124	                var authEvent = new AuthEvent(
125	                    Id: Guid.NewGuid(),
126	                    OccurredAt: issuedAt,
127	                    EventType: AuthEventType.InvitationIssued,
128	                    UserId: issuedByUserId,
129	                    Outcome: "success");
130	                await _authEventRepository.RecordAsync(authEvent, tx);
131	
132	                tx.Commit();
133	
134	                _logger.LogInformation(
135	                    "Invitation issued by {IssuedByUserId}", issuedByUserId);
136	
137	                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
138	            }
139	            catch
140	            {
141	                tx.Rollback();
142	                throw;
143	            }
144	        }, cancellationToken);
145	    }
146	
147	    public async Task<(User User, Guid? BoardId)> AcceptAsync(
148	        string rawToken,
149	        string googleEmail,
150	        string googleSub,
151	        string displayName,
152	        CancellationToken cancellationToken = default)
153	    {
154	        Verify.That(rawToken).IsNotNull().IsNotEmpty();
155	        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
156	        Verify.That(googleSub).IsNotNull().IsNotEmpty();
157	        Verify.That(displayName).IsNotNull().IsNotEmpty();
158	
159	        return await RetryPolicy.ExecuteAsync(async ct =>
160	        {
161	            var tokenHash = InvitationToken.HashRaw(rawToken);
162	            var acceptedAt = DateTimeOffset.UtcNow;
163	            var newUserId = Guid.NewGuid();
164	
165	            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
166	            try
167	            {
168	                // Atomic gate: marks consumed_at — serialises concurrent accepts.
169	                // consumed_by_user_id is set separately below (after user is created) to avoid
170	                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
171	                // default, unlike previous versions.
172	                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
173	                if (!consumed)
174	                    throw new NotFoundException(
175	                        "invite.invalid",
176	                        "This invitation is no longer valid. Please request a new one.");
177	
178	                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
179	                if (invitation is null || !invitation.EmailMatches(googleEmail))
180	                    throw new BusinessRuleException(
181	                        "invite.email_mismatch",
