        Verify.That(boardId).IsNotDefault();

        const string sql = "SELECT COUNT(*) FROM lanes WHERE board_id = @boardId";
        return await _connection.QuerySingleAsync<int>(
            sql, new { boardId = boardId.ToString("D") }, transaction: tx);
    }
}

