using System.Data;
using Dapper;
using FluentValidation;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;

namespace Kanban.DataAccess.Repositories;

public sealed class LaneRepository : ILaneRepository
{
    private readonly IDbConnection _connection;

    public LaneRepository(IDbConnection connection)
    {
        ArgumentNullException.ThrowIfNull(connection);
        _connection = connection;
    }

    public async Task<IReadOnlyList<Lane>> FindByBoardAsync(Guid boardId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);

        const string sql = """
            SELECT id, board_id AS BoardId, name, position, version, created_at AS CreatedAt
            FROM lanes
            WHERE board_id = @boardId
            ORDER BY position ASC
            """;

        var results = await _connection.QueryAsync<Lane>(
            sql, new { boardId = boardId.ToString("D") }, transaction: tx);
        return results.AsList();
    }

    public async Task<Lane?> FindByIdAsync(Guid laneId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);

        const string sql = """
            SELECT id, board_id AS BoardId, name, position, version, created_at AS CreatedAt
            FROM lanes
            WHERE id = @laneId
            """;

        return await _connection.QuerySingleOrDefaultAsync<Lane>(
            sql, new { laneId = laneId.ToString("D") }, transaction: tx);
    }

    public async Task InsertAsync(Lane lane, IDbTransaction tx)
    {
        ArgumentNullException.ThrowIfNull(lane);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            INSERT INTO lanes (id, board_id, name, position, version, created_at)
            VALUES (@id, @boardId, @name, @position, @version, @createdAt)
            """;

        await _connection.ExecuteAsync(sql, new
        {
            id = lane.Id.ToString("D"),
            boardId = lane.BoardId.ToString("D"),
            name = lane.Name,
            position = lane.Position,
            version = lane.Version,
            createdAt = lane.CreatedAt.ToString("o"),
        }, transaction: tx);
    }

    public async Task UpdateNameAsync(Guid laneId, string name, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("name") }.ValidateAndThrow(name);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "UPDATE lanes SET name = @name WHERE id = @laneId";
        await _connection.ExecuteAsync(sql,
            new { laneId = laneId.ToString("D"), name }, transaction: tx);
    }

    public async Task<int> UpdatePositionAsync(Guid laneId, int newPosition, int expectedVersion, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE lanes
            SET position = @newPosition, version = version + 1
            WHERE id = @laneId
              AND version = @expectedVersion
            """;

        return await _connection.ExecuteAsync(sql, new
        {
            laneId = laneId.ToString("D"),
            newPosition,
            expectedVersion,
        }, transaction: tx);
    }

    public async Task ShiftPositionsAsync(Guid boardId, int fromPosition, int toPosition, int delta, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE lanes
            SET position = position + @delta
            WHERE board_id = @boardId
              AND position >= @fromPosition
              AND position <= @toPosition
            """;

        await _connection.ExecuteAsync(sql, new
        {
            boardId = boardId.ToString("D"),
            fromPosition,
            toPosition,
            delta,
        }, transaction: tx);
    }

    public async Task DeleteAsync(Guid laneId, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "DELETE FROM lanes WHERE id = @laneId";
        await _connection.ExecuteAsync(sql,
            new { laneId = laneId.ToString("D") }, transaction: tx);
    }

    public async Task<int> CountInBoardAsync(Guid boardId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);

        const string sql = "SELECT COUNT(*) FROM lanes WHERE board_id = @boardId";
        return await _connection.QuerySingleAsync<int>(
            sql, new { boardId = boardId.ToString("D") }, transaction: tx);
    }
}

using Kanban.Contracts;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;

namespace Kanban.Business.Transforms;

public static class UserTransforms
{
    public static CurrentUserDto ToDto(User user)
    {
        ArgumentNullException.ThrowIfNull(user);
        return new CurrentUserDto
        {
            Id = user.Id,
            Email = user.Email,
            DisplayName = user.DisplayName,
            SystemRole = user.SystemRole == SystemRole.Admin ? "admin" : "standard",
            RegisteredAt = user.RegisteredAt,
            LastSignInAt = user.LastSignInAt,
        };
    }
}

using FluentValidation;
using Kanban.Contracts;
using Kanban.Domain;
using Kanban.Domain.Entities;

namespace Kanban.Business.Transforms;

public static class InvitationTransforms
{
    public static IssueInviteResponse ToResponse(Invitation invitation, string rawToken,
                                                  string frontendBaseUrl)
    {
        ArgumentNullException.ThrowIfNull(invitation);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("rawToken") }.ValidateAndThrow(rawToken);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("frontendBaseUrl") }.ValidateAndThrow(frontendBaseUrl);
        return new IssueInviteResponse
        {
            Token = rawToken,
            RedemptionLink = $"{frontendBaseUrl}/accept/{rawToken}",
            ExpiresAt = invitation.ExpiresAt,
        };
    }

    public static IssueInviteResponse ToResponse(string rawToken, DateTimeOffset expiresAt,
                                                   string frontendBaseUrl)
    {
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("rawToken") }.ValidateAndThrow(rawToken);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("frontendBaseUrl") }.ValidateAndThrow(frontendBaseUrl);
        return new IssueInviteResponse
        {
            Token = rawToken,
            RedemptionLink = $"{frontendBaseUrl}/accept/{rawToken}",
            ExpiresAt = expiresAt,
        };
    }
}

using System.Data;
using FluentValidation;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Kanban.Domain.Exceptions;
using Kanban.Domain.ValueObjects;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class InvitationService : IInvitationService
{
    private readonly IUserRepository _userRepository;
    private readonly IInvitationRepository _invitationRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IBoardMemberRepository _boardMemberRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<InvitationService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public InvitationService(
        IUserRepository userRepository,
        IInvitationRepository invitationRepository,
        IAuthEventRepository authEventRepository,
        IBoardMemberRepository boardMemberRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<InvitationService> logger)
    {
        ArgumentNullException.ThrowIfNull(userRepository);
        ArgumentNullException.ThrowIfNull(invitationRepository);
        ArgumentNullException.ThrowIfNull(authEventRepository);
        ArgumentNullException.ThrowIfNull(boardMemberRepository);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _userRepository = userRepository;
        _invitationRepository = invitationRepository;
        _authEventRepository = authEventRepository;
        _boardMemberRepository = boardMemberRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
        string email,
        Guid issuedByUserId,
        SystemRole callerRole,
        string frontendBaseUrl,
        Guid? boardId = null,
        BoardRole? boardRole = null,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("email") }.ValidateAndThrow(email);
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("issuedByUserId") }.ValidateAndThrow(issuedByUserId);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("frontendBaseUrl") }.ValidateAndThrow(frontendBaseUrl);

        // System invitations require admin. Board invitations are pre-authorised by the caller
        // (BoardMembershipService checks board role before calling here).
        if (boardId is null && callerRole != SystemRole.Admin)
            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
                if (existing is not null)
                {
                    var refreshToken = InvitationToken.Generate();
                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
                    await _invitationRepository.RefreshTokenAsync(
                        existing.Id, refreshToken.Hash, newExpiry, tx);
                    tx.Commit();
                    _logger.LogInformation(
                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
                }

                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
                if (registeredUser is not null)
                    throw new ConflictException(
                        "invite.already_registered", "This email address is already registered.");

                var token = InvitationToken.Generate();
                var issuedAt = DateTimeOffset.UtcNow;
                var invitation = new Invitation(
                    id: Guid.NewGuid(),
                    email: email,
                    issuedByUserId: issuedByUserId,
                    tokenHash: token.Hash,
                    issuedAt: issuedAt,
                    expiresAt: issuedAt.AddDays(7),
                    consumedAt: null,
                    consumedByUserId: null,
                    boardId: boardId,
                    boardRole: boardRole);

                await _invitationRepository.InsertAsync(invitation, tx);

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: issuedAt,
                    EventType: AuthEventType.InvitationIssued,
                    UserId: issuedByUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation(
                    "Invitation issued by {IssuedByUserId}", issuedByUserId);

                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }

    public async Task<(User User, Guid? BoardId)> AcceptAsync(
        string rawToken,
        string googleEmail,
        string googleSub,
        string displayName,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("rawToken") }.ValidateAndThrow(rawToken);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("googleEmail") }.ValidateAndThrow(googleEmail);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("googleSub") }.ValidateAndThrow(googleSub);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("displayName") }.ValidateAndThrow(displayName);

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            var tokenHash = InvitationToken.HashRaw(rawToken);
            var acceptedAt = DateTimeOffset.UtcNow;
            var newUserId = Guid.NewGuid();

            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                // Atomic gate: marks consumed_at — serialises concurrent accepts.
                // consumed_by_user_id is set separately below (after user is created) to avoid
                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
                // default, unlike previous versions.
                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
                if (!consumed)
                    throw new NotFoundException(
                        "invite.invalid",
                        "This invitation is no longer valid. Please request a new one.");

                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
                if (invitation is null || !invitation.EmailMatches(googleEmail))
                    throw new BusinessRuleException(
                        "invite.email_mismatch",
                        "This invitation was issued to a different email address.");

                var existingUser = await _userRepository.FindByEmailAsync(invitation.Email, tx);
                if (existingUser is not null)
                    throw new ConflictException(
                        "invite.already_registered",
                        "This email address is already registered.");

                var user = new User(
                    id: newUserId,
                    email: invitation.Email,
                    displayName: displayName,
                    systemRole: SystemRole.Standard,
                    googleSub: googleSub,
                    registeredAt: acceptedAt,
                    lastSignInAt: null);

                await _userRepository.InsertAsync(user, tx);
                await _invitationRepository.RecordConsumerAsync(tokenHash, newUserId, tx);

                if (invitation.BoardId.HasValue && invitation.BoardRole.HasValue)
                {
                    var boardMember = new BoardMember(
                        id: Guid.NewGuid(),
                        boardId: invitation.BoardId.Value,
                        userId: newUserId,
                        role: invitation.BoardRole.Value,
                        invitedByUserId: invitation.IssuedByUserId,
                        joinedAt: acceptedAt);
                    await _boardMemberRepository.InsertAsync(boardMember, tx);
                }

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: acceptedAt,
                    EventType: AuthEventType.InvitationAccepted,
                    UserId: newUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation("Invitation accepted by user {UserId}", newUserId);
                return (user, invitation.BoardId);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

using System.Data;
using System.Security.Claims;
using FluentValidation;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class AuthService : IAuthService
{
    private readonly IUserRepository _userRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<AuthService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public AuthService(
        IUserRepository userRepository,
        IAuthEventRepository authEventRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<AuthService> logger)
    {
        ArgumentNullException.ThrowIfNull(userRepository);
        ArgumentNullException.ThrowIfNull(authEventRepository);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _userRepository = userRepository;
        _authEventRepository = authEventRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<CurrentUserDto?> GetCurrentUserAsync(
        Guid userId,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("userId") }.ValidateAndThrow(userId);
        var user = await _userRepository.FindByIdAsync(userId);
        return user is null ? null : UserTransforms.ToDto(user);
    }

    public async Task HandleSignInAsync(
        string googleSub,
        string email,
        ClaimsIdentity claimsIdentity,
        CancellationToken cancellationToken = default)
    {
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("googleSub") }.ValidateAndThrow(googleSub);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("email") }.ValidateAndThrow(email);
        ArgumentNullException.ThrowIfNull(claimsIdentity);

        await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var user = await _userRepository.FindByGoogleSubAsync(googleSub, tx);

                if (user is null)
                {
                    var userByEmail = await _userRepository.FindByEmailAsync(email, tx);
                    if (userByEmail is not null && userByEmail.GoogleSub is null)
                    {
                        await _userRepository.LinkGoogleSubAsync(userByEmail.Id, googleSub, tx);
                        userByEmail.LinkGoogleIdentity(googleSub);
                        user = userByEmail;
                    }
                }

                if (user is not null)
                {
                    claimsIdentity.AddClaim(new Claim("user_id", user.Id.ToString()));
                    claimsIdentity.AddClaim(new Claim("system_role",
                        user.SystemRole == SystemRole.Admin ? "admin" : "standard"));

                    var signedInAt = DateTimeOffset.UtcNow;
                    await _userRepository.UpdateLastSignInAsync(user.Id, signedInAt, tx);

                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: signedInAt,
                        EventType: AuthEventType.SignIn,
                        UserId: user.Id,
                        Outcome: "success");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogInformation(
                        "User {UserId} signed in with role {SystemRole}", user.Id, user.SystemRole);
                }
                else
                {
                    var authEvent = new AuthEvent(
                        Id: Guid.NewGuid(),
                        OccurredAt: DateTimeOffset.UtcNow,
                        EventType: AuthEventType.SignIn,
                        UserId: null,
                        Outcome: "unregistered");
                    await _authEventRepository.RecordAsync(authEvent, tx);

                    _logger.LogWarning("Unregistered Google user attempted sign-in");
                }

                tx.Commit();
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

